        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the variable `curr_sgl_dma` not being initialized, which led to a compile warning. Uninitialized variables can lead to undefined behavior, making the code less reliable and potentially causing issues during execution. Initializing the variable to `0` ensures that it has a defined value before being used in the function.

        Commit message:
        crypto: hisilicon - init curr_sgl_dma to fix compile warning

Just init curr_sgl_dma = 0 to avoid compile warning.

Fixes: dfed0098ab91 ("crypto: hisilicon - add hardware SGL support")
Reported-by: kbuild test robot <lkp@intel.com>
Signed-off-by: Zhou Wang <wangzhou1@hisilicon.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>  

        Patch:
          */
 struct hisi_acc_hw_sgl *
 hisi_acc_sg_buf_map_to_hw_sgl(struct device *dev,
 			      struct scatterlist *sgl,
 			      struct hisi_acc_sgl_pool *pool,
 			      u32 index, dma_addr_t *hw_sgl_dma)
 {
 	struct hisi_acc_hw_sgl *curr_hw_sgl;
-	dma_addr_t curr_sgl_dma;
+	dma_addr_t curr_sgl_dma = 0;
 	struct acc_hw_sge *curr_hw_sge;
 	struct scatterlist *sg;
 	int sg_n = sg_nents(sgl);
 	int i, ret;

 	if (!dev || !sgl || !pool || !hw_sgl_dma || sg_n > acc_sgl_sge_nr)
 		return ERR_PTR(-EINVAL);

 	ret = dma_map_sg(dev, sgl, sg_n, DMA_BIDIRECTIONAL);
 	if (!ret)
 		return ERR_PTR(-EINVAL);

 	curr_hw_sgl = acc_get_sgl(pool, index, &curr_sgl_dma);
 	if (!curr_hw_sgl) {
 		ret = -ENOMEM;
 		goto err_unmap_sg;
 	}
 	curr_hw_sgl->entry_length_in_sgl = acc_sgl_sge_nr;
 	curr_hw_sge = curr_hw_sgl->sge_entries;

 	for_each_sg(sgl, sg, sg_n, i) {
 		sg_map_to_hw_sg(sg, curr_hw_sge);
 		inc_hw_sgl_sge(curr_hw_sgl);
 		curr_hw_sge++;
 	}

 	update_hw_sgl_sum_sge(curr_hw_sgl, acc_sgl_sge_nr);
 	*hw_sgl_dma = curr_sgl_dma;

 	return curr_hw_sgl;

 err_unmap_sg:
 	dma_unmap_sg(dev, sgl, sg_n, DMA_BIDIRECTIONAL);
 	return ERR_PTR(ret);
 }
 EXPORT_SYMBOL_GPL(hisi_acc_sg_buf_map_to_hw_sgl);


